// ─── Storage ─────────────────────────────────────────────────────────────────
async function loadJSON(key,fb){
  try{const r=await window.storage.get(key,true);return JSON.parse(r.value);}
  catch(e){try{await window.storage.set(key,JSON.stringify(fb),true);}catch(_){}return fb;}
}
async function saveJSON(key,v){try{await window.storage.set(key,JSON.stringify(v),true);}catch(e){console.error(e);}}

// ─── Error Boundary ───────────────────────────────────────────────────────────
class ErrorBoundary extends React.Component{
  constructor(p){super(p);this.state={err:null};}
  static getDerivedStateFromError(e){return{err:e};}
  render(){
    if(this.state.err)return(
      <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:"#F4F0E4",padding:24,fontFamily:"'Public Sans',system-ui"}}>
        <div style={{background:"#fff",border:"1px solid #E4DFCF",borderRadius:12,padding:28,maxWidth:540}}>
          <div style={{fontWeight:700,color:"#A23B2E",marginBottom:8}}>Ocurrió un error en el sistema</div>
          <pre style={{fontSize:11.5,whiteSpace:"pre-wrap",background:"#F7F4EC",padding:10,borderRadius:8,color:"#7A2E22",maxHeight:180,overflow:"auto"}}>{String(this.state.err?.message||this.state.err)}</pre>
          <button onClick={()=>this.setState({err:null})} style={{marginTop:12,background:"#2F5233",color:"#fff",border:"none",borderRadius:7,padding:"8px 14px",cursor:"pointer",fontWeight:600}}>Reintentar</button>
        </div>
      </div>
    );
    return this.props.children;
  }
}

