      {C("Dirección Regional Sur","colorRegionSur")}
      {C("Dirección Regional Oeste","colorRegionOeste")}
      {C("Dirección Regional Meseta Central","colorRegionMeseta")}

      <div style={{height:1,background:"#EEE9D9",margin:"14px 0"}}/>
