// ─── App principal ────────────────────────────────────────────────────────────
// ─── Chat DM (mensajería directa) ───────────────────────────────────────────
function convKey(u1, u2) {
  return [u1, u2].sort().join("__");
}

function ChatDM({user, usuarios}) {
  const[abierto,setAbierto]=useState(false);
  const[convActiva,setConvActiva]=useState(null);// username del interlocutor
  const[conversaciones,setConversaciones]=useState({});// {convId: [{id,fecha,usuario,nombre,rol,texto}]}
  const[nuevo,setNuevo]=useState("");
  const endRef=React.useRef(null);

  // Interlocutores disponibles según el rol
  const interlocutores=useMemo(()=>{
    if(user.rol==="admin"){
      return usuarios.filter(u=>u.usuario!==user.usuario);
    }
    return usuarios.filter(u=>u.rol==="admin");
  },[user,usuarios]);

  async function cargarConvs(){
    const convIds=interlocutores.map(u=>convKey(user.usuario,u.usuario));
    const resultado={};
    for(const cid of convIds){
      try{const r=await window.storage.get("crecer-dm-"+cid,true);resultado[cid]=JSON.parse(r.value)||[];}
      catch(e){resultado[cid]=[];}
    }
    setConversaciones(resultado);
  }

  useEffect(()=>{
    if(!abierto)return;
    cargarConvs();
    const t=setInterval(cargarConvs,5000);
    return()=>clearInterval(t);
  },[abierto,interlocutores]);

  useEffect(()=>{
    if(endRef.current&&endRef.current.scrollIntoView)
      try{endRef.current.scrollIntoView({behavior:"smooth"});}catch(_){}
  },[conversaciones,convActiva]);

  async function enviar(){
    if(!nuevo.trim()||!convActiva)return;
    const cid=convKey(user.usuario,convActiva);
    const msg={id:"dm-"+Date.now(),fecha:new Date().toISOString(),usuario:user.usuario,nombre:user.nombre,rol:user.rol,texto:nuevo.trim()};
    const current=conversaciones[cid]||[];
    const next=[...current,msg];
    setConversaciones(prev=>({...prev,[cid]:next}));
    await window.storage.set("crecer-dm-"+cid,JSON.stringify(next),true);
    setNuevo("");
  }

  const msgsActivos=convActiva?conversaciones[convKey(user.usuario,convActiva)]||[]:[];
  const interlocutorInfo=usuarios.find(u=>u.usuario===convActiva);
  const noLeidos=(cid)=>(conversaciones[cid]||[]).filter(m=>m.usuario!==user.usuario).length;

  const rolColor={admin:"#2F5233",viewer:"#5B6B63",viewer_regional:"#8A5C00",productor:"#1A5C8A"};

  return <div style={{position:"fixed",bottom:24,right:24,zIndex:200,display:"flex",flexDirection:"column",alignItems:"flex-end",gap:8}}>
    {/* Panel del chat */}
    {abierto&&<div style={{width:300,height:440,background:"#fff",borderRadius:12,boxShadow:"0 8px 32px rgba(0,0,0,0.18)",display:"flex",flexDirection:"column",border:"1px solid #E4DFCF",overflow:"hidden"}}>

      {/* Cabecera del panel */}
      <div style={{background:"var(--color-primary)",color:"#fff",padding:"10px 14px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        {convActiva
          ?<div style={{display:"flex",alignItems:"center",gap:8}}>
              <button onClick={()=>setConvActiva(null)} style={{background:"transparent",border:"none",color:"#fff",cursor:"pointer",padding:0,fontSize:16}}>←</button>
              <div>
                <div style={{fontWeight:700,fontSize:13}}>{interlocutorInfo?.nombre||convActiva}</div>
                <div style={{fontSize:10,opacity:0.8}}>{ROL_LABEL[interlocutorInfo?.rol]||""}</div>
              </div>
            </div>
          :<div style={{fontWeight:700,fontSize:13}}>💬 Mensajes directos</div>
        }
        <button onClick={()=>setAbierto(false)} style={{background:"transparent",border:"none",color:"#fff",cursor:"pointer",fontSize:18,lineHeight:1}}>×</button>
      </div>

      {/* Lista de conversaciones */}
      {!convActiva&&<div style={{flex:1,overflowY:"auto",padding:8}}>
        {interlocutores.length===0
          ?<div style={{textAlign:"center",color:"#9A9482",fontSize:12,marginTop:30}}>No hay usuarios disponibles para chatear.</div>
          :interlocutores.map(u=>{
            const cid=convKey(user.usuario,u.usuario);
            const msgs=conversaciones[cid]||[];
            const ultimo=msgs[msgs.length-1];
            const sinLeer=msgs.filter(m=>m.usuario!==user.usuario).length;
            const Icon=ROL_ICON[u.rol]||Eye;
            return <div key={u.usuario} onClick={()=>{setConvActiva(u.usuario);setNuevo("");}} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 10px",borderRadius:8,cursor:"pointer",marginBottom:4,background:"#F7F4EC",border:"1px solid #E4DFCF"}}>
              <Avatar foto={u.foto} nombre={u.nombre} size={34}/>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontWeight:700,fontSize:13,display:"flex",alignItems:"center",gap:6}}>
                  {u.nombre}
                  {sinLeer>0&&<span style={{background:"var(--color-danger)",color:"#fff",borderRadius:10,padding:"1px 6px",fontSize:10}}>{sinLeer}</span>}
                </div>
                <div style={{fontSize:11,color:"#8A7B4E",display:"flex",alignItems:"center",gap:4}}>
                  <Icon size={10}/>{ROL_LABEL[u.rol]||u.rol}
                </div>
                {ultimo&&<div style={{fontSize:10.5,color:"#9A9482",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis",marginTop:2}}>
                  {ultimo.nombre.split(" ")[0]}: {ultimo.texto}
                </div>}
              </div>
            </div>;
          })
        }
      </div>}

      {/* Conversación activa */}
      {convActiva&&<>
        <div style={{flex:1,overflowY:"auto",padding:"8px 10px",display:"flex",flexDirection:"column",gap:8}}>
          {msgsActivos.length===0
            ?<div style={{textAlign:"center",color:"#9A9482",fontSize:12,marginTop:30}}>Iniciá la conversación escribiendo abajo.</div>
            :msgsActivos.map(m=>{
              const esPropio=m.usuario===user.usuario;
              const f=new Date(m.fecha);
              const ts=`${String(f.getDate()).padStart(2,"0")}/${String(f.getMonth()+1).padStart(2,"0")} ${String(f.getHours()).padStart(2,"0")}:${String(f.getMinutes()).padStart(2,"0")}`;
              return <div key={m.id} style={{display:"flex",flexDirection:"column",alignItems:esPropio?"flex-end":"flex-start"}}>
                <div style={{fontSize:10,color:"#9A9482",marginBottom:2}}>{esPropio?"Vos":m.nombre} · {ts}</div>
                <div style={{
                  background:esPropio?"var(--color-primary)":"#F0ECDD",
                  color:esPropio?"#fff":"#23362B",
                  borderRadius:esPropio?"10px 10px 2px 10px":"10px 10px 10px 2px",
                  padding:"6px 10px",fontSize:12.5,maxWidth:220,wordBreak:"break-word",lineHeight:1.4,
                }}>{m.texto}</div>
              </div>;
            })
          }
          <div ref={endRef}/>
        </div>
        <div style={{padding:"7px 10px",borderTop:"1px solid #EEE9D9",display:"flex",gap:6}}>
          <input
            style={{...iS,flex:1,fontSize:12.5,padding:"6px 8px"}}
            value={nuevo}
            onChange={e=>setNuevo(e.target.value)}
            onKeyDown={e=>e.key==="Enter"&&!e.shiftKey&&(e.preventDefault(),enviar())}
            placeholder="Escribí un mensaje…"
          />
          <button onClick={enviar} style={{background:"var(--color-primary)",color:"#fff",border:"none",borderRadius:7,padding:"6px 10px",cursor:"pointer",fontWeight:600,fontSize:12}}>→</button>
        </div>
      </>}
    </div>}

    {/* Botón flotante */}
    <button onClick={()=>{setAbierto(a=>!a);if(!abierto)cargarConvs();}}
      style={{width:50,height:50,borderRadius:"50%",background:"var(--color-primary)",color:"#fff",border:"none",cursor:"pointer",fontSize:22,boxShadow:"0 4px 16px rgba(0,0,0,0.25)",display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>
      💬
      {/* Badge de mensajes sin leer */}
      {(()=>{
        const total=interlocutores.reduce((s,u)=>{
          const cid=convKey(user.usuario,u.usuario);
          return s+(conversaciones[cid]||[]).filter(m=>m.usuario!==user.usuario).length;
        },0);
        return total>0?<span style={{position:"absolute",top:2,right:2,background:"var(--color-danger)",color:"#fff",borderRadius:10,padding:"1px 5px",fontSize:10,lineHeight:1.4,fontWeight:700}}>{total}</span>:null;
      })()}
    </button>
  </div>;
}


// ─── Simulador de cuotas ──────────────────────────────────────────────────────
function SimuladorCuotas({lineas,onClose,onPrint}){
  const[lineaId,setLineaId]=useState(lineas[0]?.id||"");
  const linea=useMemo(()=>lineas.find(l=>l.id===lineaId),[lineaId,lineas]);
  const[destinoId,setDestinoId]=useState(()=>lineas[0]?.destinos?.[0]?.id||"");
  const[monto,setMonto]=useState("");
  const[fecha,setFecha]=useState(todayStr());
  const[esAsociado,setEsAsociado]=useState(false);
  useEffect(()=>{const l=lineas.find(x=>x.id===lineaId);if(l?.destinos?.length){setDestinoId(l.destinos[0].id);}},[lineaId,lineas]);
  const destino=useMemo(()=>linea?.destinos?.find(d=>d.id===destinoId),[linea,destinoId]);
  const tasa=esAsociado?(linea?.tasaFinancieraAsociado||15):(linea?.tasaFinanciera||20);
  const tasas={mora:linea?.tasaMora||15,punitorio:linea?.tasaPunitorio||15};
  const preview=useMemo(()=>{
    if(!destino||!monto||Number(monto)<=0||!fecha)return[];
    const cuotas=generarCronograma(fecha,Number(monto),destino.mesesCuotas,tasa,linea?.periodicidadInteres);
    const credTemp={monto:Number(monto),cuotas};
    return calcularFilas(credTemp,tasas);
  },[destino,monto,fecha,tasa,tasas]);
  const totalCap=preview.reduce((s,f)=>s+(f.cap?.monto||0),0);
  const totalInt=preview.reduce((s,f)=>s+(f.int?.monto||0),0);

  function generarPDF(){
    const filasHTML=preview.map(f=>{
      const capL=f.cap?`Cap ${f.cap.numero}/${f.nCaps}`:"";
      const intL=f.int?`Int ${f.int.numero}/${f.nInts}`:"";
      const total=r2((f.cap?.monto||0)+(f.int?.monto||0));
      return `<tr>
        <td>${[capL,intL].filter(Boolean).join(" · ")||"-"}</td>
        <td>${f.mes}</td>
        <td>${fmtDate(f.fechaVencimiento)}</td>
        <td>${f.cap?money(f.cap.monto):"-"}</td>
        <td>${f.int?money(f.int.monto):"-"}</td>
        <td style="font-weight:700">${money(total)}</td>
      </tr>`;
    }).join("");
    const html=`
      <div style="text-align:center;margin-bottom:14px">
        <div style="font-weight:800;font-size:15pt">Simulación de crédito</div>
        <div style="font-size:10pt;color:#555">Sistema CRECER — Ministerio de Producción, Provincia del Chubut</div>
      </div>
      <table style="margin-bottom:14px">
        <tr><td style="width:50%"><b>Línea de crédito:</b> ${linea?.nombre||"-"}</td><td><b>Destino:</b> ${destino?.nombre||"-"}</td></tr>
        <tr><td><b>Monto simulado:</b> ${money(Number(monto)||0)}</td><td><b>Fecha de otorgamiento:</b> ${fmtDate(fecha)}</td></tr>
        <tr><td><b>Condición:</b> ${esAsociado?"Asociado / Cooperativa":"General"}</td><td><b>Tasa financiera aplicada:</b> ${tasa}% anual</td></tr>
      </table>
      <table>
        <thead><tr><th>N° cuota</th><th>Mes</th><th>Vencimiento</th><th>Capital</th><th>Interés financiero</th><th>Total cuota</th></tr></thead>
        <tbody>
          ${filasHTML}
          <tr style="background:#f0f0f0;font-weight:700">
            <td colspan="3">TOTAL</td>
            <td>${money(totalCap)}</td>
            <td>${money(totalInt)}</td>
            <td>${money(r2(totalCap+totalInt))}</td>
          </tr>
        </tbody>
      </table>
      <div style="margin-top:16px;font-size:9pt;color:#777">Simulación generada el ${fmtDate(todayStr())}. Los valores son estimativos y pueden variar según la fecha real de otorgamiento y modificaciones en las tasas vigentes.</div>
    `;
    onPrint(html);
  }

  return <div style={{position:"fixed",inset:0,background:"rgba(30,25,10,0.55)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:150,padding:16}}>
    <div style={{background:"#fff",borderRadius:12,width:720,maxWidth:"100%",maxHeight:"92vh",display:"flex",flexDirection:"column",boxShadow:"0 20px 60px rgba(0,0,0,0.2)"}}>
      <div style={{padding:"14px 20px",borderBottom:"1px solid #EEE9D9",display:"flex",justifyContent:"space-between",alignItems:"center",background:"var(--gradiente-banda)",borderRadius:"12px 12px 0 0"}}>
        <div style={{fontWeight:700,color:"#fff",fontSize:16}}>🧮 Simulador de cuotas</div>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          {preview.length>0&&<button onClick={generarPDF} style={{background:"#fff",color:"var(--color-primary)",border:"none",borderRadius:7,padding:"7px 12px",cursor:"pointer",fontWeight:700,fontSize:12.5,display:"flex",alignItems:"center",gap:6}}>
            <Printer size={14}/>Generar PDF
          </button>}
          <button onClick={onClose} style={{background:"transparent",border:"none",color:"#fff",cursor:"pointer",fontSize:22,lineHeight:1}}>×</button>
        </div>
      </div>
      <div style={{padding:"18px 20px",overflowY:"auto",flex:1}}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:16}}>
          <Campo label="Línea de crédito">
            <select style={iS} value={lineaId} onChange={e=>setLineaId(e.target.value)}>
              {lineas.map(l=><option key={l.id} value={l.id}>{l.nombre} ({l.tasaFinanciera||20}% anual)</option>)}
            </select>
          </Campo>
          <Campo label="Destino">
            <select style={iS} value={destinoId} onChange={e=>setDestinoId(e.target.value)}>
              {linea?.destinos?.map(d=><option key={d.id} value={d.id}>{d.nombre} — plazo {Math.max(...d.mesesCuotas)} m. / {d.mesesCuotas.length} cuota(s) capital</option>)}
            </select>
          </Campo>
          <Campo label="Monto del crédito ($)">
            <input style={iS} type="number" value={monto} onChange={e=>setMonto(e.target.value)} placeholder="Ej: 1500000"/>
          </Campo>
          <Campo label="Fecha de otorgamiento">
            <input style={iS} type="date" min="2000-01-01" value={fecha} onChange={e=>setFecha(e.target.value)}/>
          </Campo>
        </div>
        <div style={{background:"#F0ECDD",borderRadius:8,padding:"10px 14px",marginBottom:16,display:"flex",alignItems:"center",gap:12}}>
          <label style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer",fontWeight:600,fontSize:13}}>
            <input type="checkbox" checked={esAsociado} onChange={e=>setEsAsociado(e.target.checked)} style={{width:16,height:16}}/>
            ¿Integrante de Asociación o Cooperativa Agropecuaria?
          </label>
          <span style={{color:"var(--color-primary)",fontWeight:700,fontSize:13}}>Tasa aplicable: {tasa}% anual</span>
        </div>
        {destino&&<div style={{fontSize:12.5,color:"#5B6B63",marginBottom:12}}>
          Destino: <b>{destino.nombre}</b> · Cuotas de capital en los meses: <b>{destino.mesesCuotas.join(", ")}</b> · Intereses: trimestrales sobre saldo deudor
        </div>}
        {preview.length>0&&<>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10,marginBottom:14}}>
            <div style={{background:"#EAF3EC",borderRadius:8,padding:"10px 14px",textAlign:"center"}}>
              <div style={{fontSize:11,color:"#5B6B63",fontWeight:600}}>TOTAL CAPITAL</div>
              <div style={{fontFamily:"monospace",fontSize:18,fontWeight:700,color:"var(--color-primary)"}}>{money(totalCap)}</div>
            </div>
            <div style={{background:"#EFF3FC",borderRadius:8,padding:"10px 14px",textAlign:"center"}}>
              <div style={{fontSize:11,color:"#5B6B63",fontWeight:600}}>TOTAL INTERESES</div>
              <div style={{fontFamily:"monospace",fontSize:18,fontWeight:700,color:"#1A5C8A"}}>{money(totalInt)}</div>
            </div>
            <div style={{background:"#F7F4EC",borderRadius:8,padding:"10px 14px",textAlign:"center"}}>
              <div style={{fontSize:11,color:"#5B6B63",fontWeight:600}}>TOTAL A CANCELAR</div>
              <div style={{fontFamily:"monospace",fontSize:18,fontWeight:700,color:"#23362B"}}>{money(r2(totalCap+totalInt))}</div>
            </div>
          </div>
          <div style={{border:"1px solid #E4DFCF",borderRadius:8,overflow:"auto"}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
              <thead><tr style={{background:"#F0ECDD"}}>
                <th style={TH}>N° cuota</th><th style={TH}>Mes</th><th style={TH}>Vencimiento</th>
                <th style={TH}>Capital</th><th style={TH}>Interés financiero</th><th style={TH}>Total cuota</th>
              </tr></thead>
              <tbody>
                {preview.map(f=>{
                  const capL=f.cap?`Cap ${f.cap.numero}/${f.nCaps}`:"";
                  const intL=f.int?`Int ${f.int.numero}/${f.nInts}`:"";
                  const total=r2((f.cap?.monto||0)+(f.int?.monto||0));
                  return <tr key={f.mes} style={{borderTop:"1px solid #EEE9D9"}}>
                    <td style={{...TD,fontWeight:700,whiteSpace:"nowrap"}}>{[capL,intL].filter(Boolean).join(" · ")}</td>
                    <td style={TD}>{f.mes}</td>
                    <td style={TD}>{fmtDate(f.fechaVencimiento)}</td>
                    <td style={{...TD,fontFamily:"monospace"}}>{f.cap?money(f.cap.monto):"-"}</td>
                    <td style={{...TD,fontFamily:"monospace"}}>{f.int?money(f.int.monto):"-"}</td>
                    <td style={{...TD,fontFamily:"monospace",fontWeight:700,color:"var(--color-primary)"}}>{money(total)}</td>
                  </tr>;
                })}
                <tr style={{borderTop:"2px solid #DDD",background:"#F0ECDD",fontWeight:700}}>
                  <td style={TD} colSpan={3}>TOTAL</td>
                  <td style={{...TD,fontFamily:"monospace"}}>{money(totalCap)}</td>
                  <td style={{...TD,fontFamily:"monospace"}}>{money(totalInt)}</td>
                  <td style={{...TD,fontFamily:"monospace"}}>{money(r2(totalCap+totalInt))}</td>
                </tr>
              </tbody>
            </table>
          </div>
        </>}
        {!preview.length&&monto&&Number(monto)>0&&<div style={{textAlign:"center",color:"#9A9482",padding:20}}>Completá todos los campos para ver el cronograma estimado.</div>}
        {!monto&&<div style={{textAlign:"center",color:"#9A9482",padding:20,fontSize:13}}>Completá línea, destino, monto y fecha para calcular el cronograma estimado de cuotas.</div>}
      </div>
    </div>
  </div>;
}

