const CHUBUT_MAP_VIEWBOX_BASE = {x:0,y:0,w:640,h:440};

function MapaChubutRegional({datos,tots,tema}){
  const COL = {
    "Norte": (tema&&tema.colorRegionNorte)||"#ffb109",
    "Sur": (tema&&tema.colorRegionSur)||"#ff8540",
    "Oeste": (tema&&tema.colorRegionOeste)||"#21708c",
    "Meseta Central": (tema&&tema.colorRegionMeseta)||"#5894a7",
    "Sin asignar": "#9aa0a6",
  };
  const rd = {};
  datos.forEach(d=>{ rd[d.regional] = d.cantidad; });
  const mx = Math.max(1, ...Object.values(rd));
  // Opacidad siempre alta (mapa 100% pintado); la cantidad de créditos se
  // refleja con un label numérico sobre el mapa, no con transparencia.
  function op(reg){ const v = rd[reg]||0; return 0.55 + 0.40*(v/mx); }

  const regs = [
    {id:"Norte",          n:"D.R. Norte",           c:rd["Norte"]||0,          d:"Biedma · Rawson · Gaiman · F. Ameghino"},
    {id:"Oeste",          n:"D.R. Oeste",            c:rd["Oeste"]||0,          d:"Languiñeo · Futaleufú · Cushamen"},
    {id:"Meseta Central", n:"D.R. Meseta Central",   c:rd["Meseta Central"]||0, d:"Paso de Indios · Telsen · Gastre · Mártires"},
    {id:"Sur",            n:"D.R. Sur",              c:rd["Sur"]||0,            d:"Escalante · Río Senguer · Sarmiento · Tehuelches"},
  ];

  const[hoverDept,setHoverDept]=useState(null);

  // ── Zoom / Pan ──
  const svgRef=React.useRef(null);
  const dragRef=React.useRef(null);
  const[vb,setVb]=useState({...CHUBUT_MAP_VIEWBOX_BASE});
  function clampVb(next){
    const base=CHUBUT_MAP_VIEWBOX_BASE;
    const minW=base.w*0.15, maxW=base.w*1.4;
    const w=Math.max(minW,Math.min(maxW,next.w));
    const h=w*(base.h/base.w);
    const x=Math.max(base.x-base.w*0.2,Math.min(base.x+base.w-w+base.w*0.2,next.x));
    const y=Math.max(base.y-base.h*0.2,Math.min(base.y+base.h-h+base.h*0.2,next.y));
    return{x,y,w,h};
  }
  function zoomBy(factor){
    setVb(cur=>{
      const nw=cur.w*factor, nh=cur.h*factor;
      return clampVb({x:cur.x+(cur.w-nw)/2,y:cur.y+(cur.h-nh)/2,w:nw,h:nh});
    });
  }
  function onWheel(e){
    e.preventDefault();
    const factor=e.deltaY>0?1.15:1/1.15;
    const svg=svgRef.current; if(!svg)return;
    const rect=svg.getBoundingClientRect();
    const px=(e.clientX-rect.left)/rect.width, py=(e.clientY-rect.top)/rect.height;
    setVb(cur=>{
      const nw=cur.w*factor, nh=cur.h*factor;
      return clampVb({x:cur.x+(cur.w-nw)*px,y:cur.y+(cur.h-nh)*py,w:nw,h:nh});
    });
  }
  function onMouseDown(e){ dragRef.current={startX:e.clientX,startY:e.clientY,vb0:vb}; }
  function onMouseMove(e){
    if(!dragRef.current)return;
    const svg=svgRef.current; if(!svg)return;
    const rect=svg.getBoundingClientRect();
    const dx=(e.clientX-dragRef.current.startX)/rect.width*dragRef.current.vb0.w;
    const dy=(e.clientY-dragRef.current.startY)/rect.height*dragRef.current.vb0.h;
    setVb(clampVb({x:dragRef.current.vb0.x-dx,y:dragRef.current.vb0.y-dy,w:dragRef.current.vb0.w,h:dragRef.current.vb0.h}));
  }
  function onMouseUp(){ dragRef.current=null; }
  const vbStr=`${vb.x.toFixed(1)} ${vb.y.toFixed(1)} ${vb.w.toFixed(1)} ${vb.h.toFixed(1)}`;

  return <div style={{display:"flex",gap:12,alignItems:"flex-start",flexWrap:"wrap"}}>

    {/* Mapa SVG con los 15 departamentos reales, coloreados por regional */}
    <div style={{flex:"1 1 480px",minWidth:280,position:"relative"}}>
      <div style={{position:"absolute",top:8,right:8,zIndex:5,display:"flex",flexDirection:"column",gap:4}}>
        <button onClick={()=>zoomBy(0.75)} title="Acercar" style={{width:26,height:26,borderRadius:6,border:"1px solid #9BBAD4",background:"#fff",cursor:"pointer",fontWeight:700,fontSize:14,lineHeight:1,color:"#1A2B4A"}}>+</button>
        <button onClick={()=>zoomBy(1/0.75)} title="Alejar" style={{width:26,height:26,borderRadius:6,border:"1px solid #9BBAD4",background:"#fff",cursor:"pointer",fontWeight:700,fontSize:14,lineHeight:1,color:"#1A2B4A"}}>–</button>
        <button onClick={()=>setVb({...CHUBUT_MAP_VIEWBOX_BASE})} title="Restablecer vista" style={{width:26,height:26,borderRadius:6,border:"1px solid #9BBAD4",background:"#fff",cursor:"pointer",fontSize:11,lineHeight:1,color:"#1A2B4A"}}>⟲</button>
      </div>
      <svg ref={svgRef} viewBox={vbStr} width="100%"
        onWheel={onWheel} onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
        style={{border:"1px solid #9BBAD4",borderRadius:10,background:"#EAF2FA",display:"block",cursor:dragRef.current?"grabbing":"grab",touchAction:"none"}}>
        {CHUBUT_DEPTOS_SVG.map((dep,i)=>
          <path key={i}
            d={dep.d}
            fill={COL[dep.regional]||COL["Sin asignar"]}
            fillOpacity={hoverDept===dep.nombre?1:op(dep.regional)}
            stroke={hoverDept===dep.nombre?"#000":"#1A2B4A"}
            strokeWidth={hoverDept===dep.nombre?1.6:0.7}
            style={{cursor:"pointer",transition:"fill-opacity .12s,stroke-width .12s"}}
            onMouseEnter={()=>setHoverDept(dep.nombre)}
            onMouseLeave={()=>setHoverDept(null)}
          >
            <title>{dep.nombre} — {dep.regional==="Meseta Central"?"Dirección Regional Meseta Central":dep.regional==="Sur"?"Dirección Regional Sur":dep.regional==="Oeste"?"Dirección Regional Oeste":"Delegación Regional Norte"} ({rd[dep.regional]||0} crédito{(rd[dep.regional]||0)!==1?"s":""})</title>
          </path>
        )}

        {/* Nombres de las Direcciones/Delegación Regionales, directamente sobre el mapa */}
        {Object.entries(CHUBUT_REG_CENTROIDE).map(([reg,pos])=>
          <g key={reg} style={{pointerEvents:"none"}}>
            <text x={pos[0]} y={pos[1]} textAnchor="middle" fontSize="15" fontWeight="800" fill="#14181F"
              stroke="#fff" strokeWidth="3.2" paintOrder="stroke" style={{fontFamily:"'Rubik',sans-serif"}}>{reg}</text>
            <text x={pos[0]} y={pos[1]+15} textAnchor="middle" fontSize="11" fontWeight="700" fill="#14181F"
              stroke="#fff" strokeWidth="2.8" paintOrder="stroke">{rd[reg]||0} crédito{(rd[reg]||0)!==1?"s":""}</text>
          </g>
        )}

        {/* Localidades principales */}
        {CHUBUT_CIUDADES.map((c,i)=>
          <g key={i} style={{pointerEvents:"none"}}>
            <circle cx={c.x} cy={c.y} r="2.2" fill="#14181F" stroke="#fff" strokeWidth="0.6"/>
            <text x={c.x+4} y={c.y+3} fontSize="7.5" fill="#14181F" stroke="#fff" strokeWidth="2" paintOrder="stroke">{c.nombre}</text>
          </g>
        )}
      </svg>
      {hoverDept&&<div style={{position:"absolute",bottom:8,left:8,background:"rgba(255,255,255,0.95)",borderRadius:6,padding:"4px 10px",fontSize:11.5,fontWeight:700,color:"#1A2B4A",boxShadow:"0 2px 6px rgba(0,0,0,0.15)"}}>{hoverDept}</div>}
      <div style={{position:"absolute",bottom:8,right:8,background:"rgba(255,255,255,0.85)",borderRadius:5,padding:"3px 8px",fontSize:9,color:"#4A6070"}}>Rueda: zoom · Arrastrar: mover</div>
    </div>

    {/* Panel de referencia */}
    <div style={{flex:"0 0 170px"}}>
      <div style={{fontWeight:700,fontSize:10,color:"#5B6B63",marginBottom:7,textTransform:"uppercase",letterSpacing:"0.06em"}}>Referencia</div>
      {regs.map(r=>
        <div key={r.id} style={{marginBottom:6,background:"#F7F4EC",borderRadius:7,padding:"7px 9px",borderLeft:`4px solid ${COL[r.id]}`}}>
          <div style={{fontWeight:700,fontSize:11,color:COL[r.id],marginBottom:2}}>{r.n}</div>
          <div style={{fontSize:9.5,color:"#5B6B63",marginBottom:3}}>{r.d}</div>
          <span style={{fontFamily:"monospace",fontWeight:700,fontSize:14,color:COL[r.id]}}>{r.c}</span>
          <span style={{fontSize:9,color:"#8A8470",marginLeft:3}}>créd.</span>
          {r.c>0 && <div style={{marginTop:3,background:"#E4DFCF",borderRadius:3,height:4,overflow:"hidden"}}>
            <div style={{width:`${Math.round((r.c/mx)*100)}%`,height:"100%",background:COL[r.id],borderRadius:3}}/>
          </div>}
        </div>
      )}
      {(rd["Sin asignar"]||0)>0 && <div style={{fontSize:9.5,color:"#9A9482",marginTop:3}}>Sin asignar: {rd["Sin asignar"]}</div>}
      <div style={{marginTop:8,fontSize:9,color:"#9A9482"}}>Total: <b style={{color:"#23362B"}}>{tots?.total||0}</b></div>
      <div style={{marginTop:10,fontSize:9,color:"#9A9482",lineHeight:1.5}}>Refleja los créditos según los filtros aplicados en la pantalla de inicio.</div>
    </div>
  </div>;
}


function CrecerApp(){
  const[loading,setLoading]=useState(true);
  const[usuarios,setUsuarios]=useState(DEFAULT_USUARIOS);
  const[lineas,setLineas]=useState(DEFAULT_LINEAS);
  const[tema,setTema]=useState(DEFAULT_TEMA);
  const[config,setConfig]=useState(DEFAULT_CONFIG);
  const[creditos,setCreditos]=useState([]);
  const[user,setUser]=useState(null);
  const[view,setView]=useState("inicio");
  const[selected,setSelected]=useState(null);
  const[showSimulador,setShowSimulador]=useState(false);
  const[showEstadoCuenta,setShowEstadoCuenta]=useState(false);
  const[busqueda,setBusqueda]=useState("");
  const[filtroEstado,setFiltroEstado]=useState("TODOS");
  const[filtroRegional,setFiltroRegional]=useState("TODAS");
  const[filtroLinea,setFiltroLinea]=useState("TODAS");
  const[filtroDestino,setFiltroDestino]=useState("TODOS");
  const[filtroAnio,setFiltroAnio]=useState("TODOS");
  const[filtroFuente,setFiltroFuente]=useState("TODAS");
  const[filtroProximoVencimiento,setFiltroProximoVencimiento]=useState(false);
  // Estado global de impresión: contenido HTML que se inyecta en #print-area y se imprime
  const[printHTML,setPrintHTML]=useState("");

  // Función global para imprimir cualquier contenido HTML
  function imprimirHTML(html){
    setPrintHTML(html);
    setTimeout(()=>{window.print();setTimeout(()=>setPrintHTML(""),1500);},80);
  }
  // Ref al bloque de gráficos + mapa para poder exportarlo a PDF con su render real (SVG incluido)
  const reporteRef=React.useRef(null);
  function imprimirReporte(){
    if(!reporteRef.current)return;
    const encabezado=`<div style="text-align:center;margin-bottom:16px">
      <div style="font-weight:800;font-size:14pt;color:#23362B">Reporte de créditos por Dirección Regional</div>
      <div style="font-size:10pt;color:#666">Sistema CRECER · ${config.ministerioNombre||"Ministerio de Producción – Provincia del Chubut"} · Generado el ${fmtDate(todayStr())}</div>
    </div>`;
    imprimirHTML(encabezado+reporteRef.current.innerHTML);
  }

  useEffect(()=>{(async()=>{
    const u=await loadJSON("crecer-usuarios",DEFAULT_USUARIOS);
    const tm=await loadJSON("crecer-tema",DEFAULT_TEMA);
    const cf=await loadJSON("crecer-config",DEFAULT_CONFIG);
    const l=await loadJSON("crecer-lineas",DEFAULT_LINEAS);
    let c=await loadJSON("crecer-creditos",null);
    if(!c){c=seedCreditos(l);await saveJSON("crecer-creditos",c);}
    setUsuarios(Array.isArray(u)&&u.length?u:DEFAULT_USUARIOS);
    setTema({...DEFAULT_TEMA,...tm});
    // Si había un logo vacío guardado de una sesión anterior, no debe tapar
    // el logo institucional oficial que ahora viene por defecto.
    setConfig({...DEFAULT_CONFIG,...cf,logo:(cf&&cf.logo)?cf.logo:DEFAULT_CONFIG.logo});
    setLineas(l);setCreditos(c);setLoading(false);
  })();},[]);

  const updateCredito=useCallback((act)=>{
    setCreditos(prev=>{
      const next=prev.map(c=>c.id===act.id?act:c);
      saveJSON("crecer-creditos",next);
      return next;
    });
    setSelected(act);
  },[]);
  const deleteCredito=useCallback((id)=>{
    setCreditos(prev=>{
      const next=prev.filter(c=>c.id!==id);
      saveJSON("crecer-creditos",next);
      return next;
    });
    setSelected(null);
  },[]);
  function createCredito(n){setCreditos(prev=>{const next=[n,...prev];saveJSON("crecer-creditos",next);return next;});setView("inicio");}
  function saveLineas(n){setLineas(n);saveJSON("crecer-lineas",n);}
  function saveTema(n){setTema(n);saveJSON("crecer-tema",n);}
  function saveCfg(n){setConfig(n);saveJSON("crecer-config",n);}
  function saveUsuarios(n){setUsuarios(n);saveJSON("crecer-usuarios",n);}
  function actualizarPerfil(ch){const next=usuarios.map(u=>u.usuario===user.usuario?{...u,...ch}:u);setUsuarios(next);saveJSON("crecer-usuarios",next);setUser(u=>({...u,...ch}));}
  async function resetearTodo(){
    const li=DEFAULT_LINEAS,cr=seedCreditos(li);
    await saveJSON("crecer-usuarios",DEFAULT_USUARIOS);await saveJSON("crecer-tema",DEFAULT_TEMA);
    await saveJSON("crecer-config",DEFAULT_CONFIG);await saveJSON("crecer-lineas",li);await saveJSON("crecer-creditos",cr);
    setUsuarios(DEFAULT_USUARIOS);setTema(DEFAULT_TEMA);setConfig(DEFAULT_CONFIG);setLineas(li);setCreditos(cr);setUser(null);
  }

  const creditosVisibles=useMemo(()=>{
    if(!user)return[];
    if(user.rol==="viewer_regional")return creditos.filter(c=>getRegional(c)===user.regional);
    if(user.rol==="productor")return creditos.filter(c=>c.productor?.dni&&c.productor.dni===user.dni);
    return creditos;
  },[creditos,user]);

  const destDisponibles=useMemo(()=>{
    const lls=filtroLinea==="TODAS"?lineas:lineas.filter(l=>l.id===filtroLinea);
    const ns=new Set();lls.forEach(l=>l.destinos.forEach(d=>ns.add(d.nombre)));return Array.from(ns);
  },[lineas,filtroLinea]);

  const aniosDisponibles=useMemo(()=>{
    const s=new Set(creditosVisibles.map(c=>c.fechaOtorgamiento?.slice(0,4)).filter(Boolean));
    return Array.from(s).sort().reverse();
  },[creditosVisibles]);

  const fuentesDisponibles=useMemo(()=>{
    const s=new Set(creditosVisibles.map(c=>c.fuenteFinanciamiento).filter(Boolean));
    return Array.from(s).sort();
  },[creditosVisibles]);

  const filtradosBase=useMemo(()=>creditosVisibles.filter(c=>{
    const est=calcularEstado(c);
    if(filtroEstado!=="TODOS"&&est!==filtroEstado)return false;
    if(filtroRegional!=="TODAS"&&getRegional(c)!==filtroRegional)return false;
    if(filtroLinea!=="TODAS"&&c.lineaId!==filtroLinea)return false;
    if(filtroDestino!=="TODOS"){const lc=lineas.find(l=>l.id===c.lineaId);const dn=lc?(findDestino(lc,c.destinoId)?.nombre||c.detalleDestino):c.detalleDestino;if(dn!==filtroDestino)return false;}
    if(filtroAnio!=="TODOS"&&c.fechaOtorgamiento?.slice(0,4)!==filtroAnio)return false;
    if(filtroFuente!=="TODAS"&&(c.fuenteFinanciamiento||"")!==filtroFuente)return false;
    if(busqueda.trim()){const q=busqueda.toLowerCase();return c.productor.nombre.toLowerCase().includes(q)||c.expediente.toLowerCase().includes(q)||c.productor.dni.toLowerCase().includes(q);}
    return true;
  }),[creditosVisibles,busqueda,filtroEstado,filtroRegional,filtroLinea,filtroDestino,filtroAnio,filtroFuente,lineas]);

  // Créditos (no cuotas) que tienen al menos una cuota pendiente venciendo dentro de los próximos 10 días
  const DIAS_PROXIMO_VENCIMIENTO=10;
  const idsProximoVencimiento=useMemo(()=>{
    const hoy=new Date(todayStr()+"T00:00:00");
    const limite=new Date(hoy); limite.setDate(limite.getDate()+DIAS_PROXIMO_VENCIMIENTO);
    const limiteStr=limite.toISOString().slice(0,10);
    const set=new Set();
    filtradosBase.forEach(credito=>{
      if(calcularEstado(credito)==="CANCELADO")return;
      const tieneVencProximo=(credito.cuotas||[]).some(c=>!c.pagada&&c.fechaVencimiento>=todayStr()&&c.fechaVencimiento<=limiteStr);
      if(tieneVencProximo)set.add(credito.id);
    });
    return set;
  },[filtradosBase]);

  const filtrados=useMemo(()=>{
    if(!filtroProximoVencimiento)return filtradosBase;
    return filtradosBase.filter(c=>idsProximoVencimiento.has(c.id));
  },[filtradosBase,filtroProximoVencimiento,idsProximoVencimiento]);

  const tots=useMemo(()=>{
    let prestado=0,cobrado=0,mora=0,noVencido=0,nC=0,nA=0,nM=0;
    const hoy=todayStr();
    filtrados.forEach(c=>{
      prestado+=c.monto;const e=calcularEstado(c);
      if(e==="CANCELADO")nC++;else if(e==="MORA")nM++;else nA++;
      (c.cuotas||[]).forEach(q=>{const s=r2((q.monto||0)-(q.montoPagado||0));cobrado+=(q.montoPagado||0);if(s>0){if(q.fechaVencimiento<hoy)mora+=s;else noVencido+=s;}});
    });
    return{prestado,cobrado,mora,noVencido,adeudado:r2(mora+noVencido),total:filtrados.length,nC,nA,nM};
  },[filtrados]);

  const datosReg=useMemo(()=>{const cnt={};filtrados.forEach(c=>{const r=getRegional(c);cnt[r]=(cnt[r]||0)+1;});return Object.entries(cnt).map(([regional,cantidad])=>({regional,cantidad}));},[filtrados]);
  const datosEst=useMemo(()=>([{name:"Al día",value:tots.nA,color:tema.success},{name:"En mora",value:tots.nM,color:tema.danger},{name:"Cancelados",value:tots.nC,color:tema.neutral}].filter(d=>d.value>0)),[tots,tema]);

  // Alertas de vencimiento próximo: cuotas que vencen en los próximos 5 días
  const tv=useMemo(()=>({
    "--color-primary":tema.primary,"--color-header-bg":tema.headerBg,
    "--color-header-text":tema.headerTextColor||"#F4F0E4","--color-bg":tema.bg,
    "--color-text-inicio":tema.textColorInicio||"#23362B",
    "--color-text-detalle":tema.textColorDetalle||"#23362B",
    "--color-success":tema.success,"--color-success-bg":shade(tema.success,.85),
    "--color-danger":tema.danger,"--color-danger-bg":shade(tema.danger,.85),
    "--color-neutral":tema.neutral,"--color-neutral-bg":shade(tema.neutral,.85),
    "--color-banda-1":tema.bandaColor1||"#ffb109",
    "--color-banda-2":tema.bandaColor2||"#ff682c",
    "--color-banda-3":tema.bandaColor3||"#21708c",
    "--color-titulo":tema.tituloColor||"#14181F",
    "--gradiente-banda":`linear-gradient(to right, ${tema.bandaColor1||"#ffb109"} 0%, ${tema.bandaColor1||"#ffb109"} 33.33%, ${tema.bandaColor2||"#ff682c"} 33.33%, ${tema.bandaColor2||"#ff682c"} 66.66%, ${tema.bandaColor3||"#21708c"} 66.66%, ${tema.bandaColor3||"#21708c"} 100%)`,
  }),[tema]);

  if(loading)return <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",color:"#8A8470",fontFamily:"'Public Sans',system-ui"}}>Cargando sistema…</div>;
  if(!user)return <div style={{...tv}}><style>{"*{box-sizing:border-box;}"}</style><LoginScreen usuarios={usuarios} onLogin={setUser} config={{...DEFAULT_CONFIG,...config}} onReset={resetearTodo}/></div>;

  const isAdmin=user.rol==="admin";

  return <div style={{minHeight:"100vh",background:"var(--color-bg)",fontFamily:"'Public Sans',system-ui,sans-serif",color:"var(--color-text-inicio)",zoom:1.08,...tv}}>
    <style>{`@import url('https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;600;700;800&family=Public+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap');
      *{box-sizing:border-box;} select{appearance:none;} input:focus,select:focus,textarea:focus{border-color:var(--color-primary)!important;}
      #print-area{display:none;}
      .sello-cancelado{
        position:absolute;top:50%;left:50%;
        transform:translate(-50%,-50%) rotate(-30deg);
        font-size:64px;font-weight:900;color:rgba(180,30,30,0.22);
        font-family:'Rubik',Arial,sans-serif;pointer-events:none;z-index:50;
        white-space:nowrap;letter-spacing:0.05em;border:6px solid rgba(180,30,30,0.2);
        padding:6px 24px;border-radius:10px;text-transform:uppercase;
      }
      @media print{
        body>*{display:none!important;}
        #print-area{display:block!important;padding:20mm;font-family:serif;font-size:11pt;line-height:1.6;}
        #print-area table{width:100%;border-collapse:collapse;margin:10px 0;}
        #print-area th,#print-area td{border:1px solid #999;padding:4px 8px;font-size:10pt;}
        #print-area th{background:#eee;font-weight:700;}
        #print-area svg{max-width:100%;height:auto;}
        #print-area .grafico-print{page-break-inside:avoid;margin-bottom:16px;}
        #print-area .grafico-titulo{font-family:Inter,sans-serif;font-size:12pt;font-weight:700;margin-bottom:6px;color:#23362B;}
        .sello-cancelado{position:fixed;font-size:110pt;}
      }
    `}</style>

    {/* Encabezado */}
    <div style={{background:"var(--color-header-bg)",backgroundImage:tema.headerBgImage?`url(${tema.headerBgImage})`:"none",backgroundSize:"cover",backgroundPosition:"center",color:"var(--color-header-text)",padding:"12px 24px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
      <div style={{display:"flex",alignItems:"center",gap:12}}>
        {config.logo?<img src={config.logo} alt="" style={{height:46,borderRadius:6}}/>:<div style={{background:shade(tema.headerBg,.25),borderRadius:8,padding:7}}><Stamp size={18}/></div>}
        <div>
          <div style={{fontFamily:"'Rubik',Georgia,sans-serif",fontWeight:700,fontSize:17,color:"var(--color-header-text)"}}>{config.sistemaNombre||"Sistema CRECER"}</div>
          <div style={{fontSize:11,color:"var(--color-header-text)",opacity:0.7}}>{config.ministerioNombre}</div>
        </div>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:12}}>
        <Avatar foto={user.foto} nombre={user.nombre} size={30}/>
        <span style={{fontSize:12,color:"var(--color-header-text)",opacity:0.85}}>{user.nombre} · <span style={{opacity:1,fontWeight:600}}>{ROL_LABEL[user.rol]||user.rol}</span></span>
        <button onClick={()=>setUser(null)} style={{background:"transparent",border:`1px solid var(--color-header-text)`,color:"var(--color-header-text)",opacity:0.85,borderRadius:7,padding:"6px 10px",cursor:"pointer",display:"flex",alignItems:"center",gap:6,fontSize:12.5}}><LogOut size={13}/>Salir</button>
      </div>
    </div>

    <div style={{display:"flex"}}>
      <div style={{width:196,padding:"18px 12px",flexShrink:0}}>
        {[
          {id:"inicio",icon:FileText,label:"Inicio"},
          {id:"simulador",icon:CreditCard,label:"Simulador de cuotas"},
          ...(isAdmin?[{id:"nuevo",icon:Plus,label:"Nuevo crédito"},{id:"lineas",icon:Landmark,label:"Líneas de crédito"},{id:"usuarios",icon:Users,label:"Usuarios"},{id:"apariencia",icon:Settings,label:"Apariencia"},{id:"encabezado",icon:Stamp,label:"Encabezado"}]:[]),
          {id:"perfil",icon:UserCircle,label:"Mi perfil"},
        ].map(({id,icon,label})=><NavItem key={id} icon={icon} label={label} active={id==="simulador"?showSimulador:view===id} onClick={()=>id==="simulador"?setShowSimulador(true):setView(id)}/>)}
      </div>

      <div style={{flex:1,padding:"20px 26px 60px",minWidth:0}}>
        {view==="inicio"&&<div>
          <BandaTricolor radius={4}/>
          <SectionTitle icon={FileText}
            title={user.rol==="productor"?"Mis créditos":"Estado general de créditos"}
            subtitle={
              user.rol==="productor"?"Créditos asociados a tu DNI/CUIT.":user.rol==="viewer_regional"?`Mostrando únicamente créditos de ${REGIONALES_NOMBRE[user.regional]}.`:""
            }/>
          <div style={{display:"flex",justifyContent:"flex-end",marginBottom:14}}>
            <Boton icon={FileSignature} onClick={()=>setShowEstadoCuenta(true)}>Estado de cuenta — Listado de productores</Boton>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:10,marginBottom:10}}>
            <KpiCard label="Créditos cargados" value={tots.total}/><KpiCard label="Cancelados" value={tots.nC} tone="neutral"/><KpiCard label="Al día" value={tots.nA} tone="success"/><KpiCard label="En mora" value={tots.nM} tone="danger"/>
            <KpiCard label={`Vencen en ${DIAS_PROXIMO_VENCIMIENTO} días`} value={idsProximoVencimiento.size} tone="warning" active={filtroProximoVencimiento} onClick={()=>setFiltroProximoVencimiento(v=>!v)}/>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:10,marginBottom:20}}>
            <KpiCard label="Monto total prestado" value={money(tots.prestado)}/><KpiCard label="Monto cobrado" value={money(tots.cobrado)} tone="success"/><KpiCard label="Adeudado en mora" value={money(tots.mora)} tone="danger"/><KpiCard label="Monto no vencido" value={money(tots.noVencido)}/><KpiCard label="Total adeudado" value={money(tots.adeudado)} tone="neutral"/>
          </div>
          <div style={{display:"flex",justifyContent:"flex-end",marginBottom:8}}>
            <Boton size="sm" variant="outline" icon={Printer} onClick={imprimirReporte}>Generar PDF de gráficos y mapa</Boton>
          </div>
          <div ref={reporteRef}>
          <div className="grafico-print" style={{display:"grid",gridTemplateColumns:"1.4fr 1fr",gap:14,marginBottom:20}}>
            <div style={{background:"#fff",border:"1px solid #E4DFCF",borderRadius:10,padding:"14px 16px"}}>
              <div className="grafico-titulo" style={{fontWeight:700,fontSize:13,color:"#23362B",marginBottom:8}}>Créditos por regional</div>
              {datosReg.length===0?<div style={{fontSize:12.5,color:"#9A9482",textAlign:"center",padding:"20px 0"}}>Sin datos.</div>:
              <ResponsiveContainer width="100%" height={200}><BarChart data={datosReg.map(d=>({...d,pct:tots.total>0?Math.round((d.cantidad/tots.total)*100):0}))} margin={{top:20,right:8,left:-16,bottom:4}}>
                <CartesianGrid strokeDasharray="3 3" stroke="#EEE9D9"/>
                <XAxis dataKey="regional" tick={{fontSize:10,fill:"#5B6B63"}} interval={0} angle={-10} textAnchor="end" height={44}/>
                <YAxis allowDecimals={false} tick={{fontSize:10,fill:"#5B6B63"}}/>
                <Tooltip contentStyle={{fontSize:12,borderRadius:8,border:"1px solid #E4DFCF"}} formatter={(v,n,p)=>[`${v} (${p.payload.pct}%)`,"Créditos"]}/>
                <Bar dataKey="cantidad" fill={tema.primary} radius={[4,4,0,0]} label={(props)=><text x={props.x+props.width/2} y={props.y-6} textAnchor="middle" fontSize={11} fontWeight={700} fill="#5B6B63">{props.payload&&props.payload.pct!=null?`${props.payload.pct}%`:""}</text>}/>
              </BarChart></ResponsiveContainer>}
            </div>
            <div style={{background:"#fff",border:"1px solid #E4DFCF",borderRadius:10,padding:"14px 16px"}}>
              <div className="grafico-titulo" style={{fontWeight:700,fontSize:13,color:"#23362B",marginBottom:8}}>Estado de cuenta</div>
              {datosEst.length===0?<div style={{fontSize:12.5,color:"#9A9482",textAlign:"center",padding:"20px 0"}}>Sin datos.</div>:
              <ResponsiveContainer width="100%" height={200}><PieChart><Pie data={datosEst} dataKey="value" nameKey="name" innerRadius={44} outerRadius={70} paddingAngle={2} label={({value})=>{const tot=datosEst.reduce((s,d)=>s+d.value,0);return tot>0?`${Math.round((value/tot)*100)}%`:"";}} labelLine={false}>{datosEst.map((d,i)=><Cell key={i} fill={d.color}/>)}</Pie><Tooltip contentStyle={{fontSize:12,borderRadius:8,border:"1px solid #E4DFCF"}} formatter={(v)=>{const tot=datosEst.reduce((s,d)=>s+d.value,0);return [`${v} (${tot>0?Math.round((v/tot)*100):0}%)`,"Créditos"];}}/><Legend wrapperStyle={{fontSize:11.5}}/></PieChart></ResponsiveContainer>}
            </div>
          </div>

          {/* Mapa de Chubut por regionales */}
          <div className="grafico-print" style={{background:"#fff",border:"1px solid #E4DFCF",borderRadius:10,padding:"16px 18px",marginBottom:20}}>
            <div className="grafico-titulo" style={{fontWeight:700,fontSize:13,color:"#23362B",marginBottom:12}}>Distribución por Dirección Regional — Chubut</div>
            <MapaChubutRegional datos={datosReg} tots={tots} tema={tema}/>
          </div>
          </div>

          {/* Filtros */}
          <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
            <div style={{position:"relative",flex:"1 1 200px"}}><Search size={13} style={{position:"absolute",left:9,top:11,color:"#9A9482"}}/><input style={{...iS,paddingLeft:28}} placeholder="Buscar productor, DNI o expediente…" value={busqueda} onChange={e=>setBusqueda(e.target.value)}/></div>
            <select style={{...iS,width:148}} value={filtroEstado} onChange={e=>setFiltroEstado(e.target.value)}><option value="TODOS">Todos los estados</option><option value="AL_DIA">Al día</option><option value="MORA">En mora</option><option value="CANCELADO">Cancelado</option></select>
            <select style={{...iS,width:178}} value={filtroRegional} onChange={e=>setFiltroRegional(e.target.value)}><option value="TODAS">Todas las regionales</option>{REGIONALES_LISTA.map(r=><option key={r} value={r}>{REGIONALES_NOMBRE[r]}</option>)}<option value="Sin asignar">Sin asignar</option></select>
            <select style={{...iS,width:160}} value={filtroLinea} onChange={e=>{setFiltroLinea(e.target.value);setFiltroDestino("TODOS");}}><option value="TODAS">Todas las líneas</option>{lineas.map(l=><option key={l.id} value={l.id}>{l.nombre}</option>)}</select>
            <select style={{...iS,width:160}} value={filtroDestino} onChange={e=>setFiltroDestino(e.target.value)}><option value="TODOS">Todos los destinos</option>{destDisponibles.map(d=><option key={d} value={d}>{d}</option>)}</select>
            <select style={{...iS,width:100}} value={filtroAnio} onChange={e=>setFiltroAnio(e.target.value)}><option value="TODOS">Todos los años</option>{aniosDisponibles.map(a=><option key={a} value={a}>{a}</option>)}</select>
            <select style={{...iS,width:190}} value={filtroFuente} onChange={e=>setFiltroFuente(e.target.value)}><option value="TODAS">Todas las fuentes</option>{fuentesDisponibles.map(f=><option key={f} value={f}>{f}</option>)}</select>
          </div>

          <div style={{background:"#fff",border:"1px solid #E4DFCF",borderRadius:10,overflow:"auto"}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:12.5}}>
              <thead><tr style={{background:"#F0ECDD",textAlign:"left"}}>
                <th style={TH}>Expediente</th><th style={TH}>Productor</th><th style={TH}>Destino</th><th style={TH}>Regional</th><th style={TH}>Monto</th><th style={TH}>Otorgado</th><th style={TH}>Estado</th><th style={TH}>Rendición</th><th style={TH}></th>
              </tr></thead>
              <tbody>{filtrados.map(c=>{
                const lc=lineas.find(l=>l.id===c.lineaId),dt=lc&&findDestino(lc,c.destinoId),reg=getRegional(c);
                return <tr key={c.id} style={{borderTop:"1px solid #EEE9D9",cursor:"pointer"}} onClick={()=>setSelected(c)}>
                  <td style={TD}>{c.expediente}</td><td style={TD}>{c.productor.nombre}</td>
                  <td style={TD}>{dt?.nombre||c.detalleDestino}</td>
                  <td style={TD}>{reg==="Sin asignar"?<span style={{color:"#B0AA94"}}>Sin asignar</span>:reg}</td>
                  <td style={{...TD,fontFamily:"monospace"}}>{money(c.monto)}</td>
                  <td style={TD}>{fmtDate(c.fechaOtorgamiento)}</td>
                  <td style={TD}><EstadoBadge estado={calcularEstado(c)}/></td>
                  <td style={TD}><RendicionBadge ok={!!c.rendicionPresentada}/></td>
                  <td style={{...TD,color:"#9A9482"}}><ChevronRight size={15}/></td>
                </tr>;
              })}
              {filtrados.length===0&&<tr><td colSpan={9} style={{...TD,textAlign:"center",color:"#9A9482",padding:28}}>No hay créditos que coincidan con los filtros.</td></tr>}
              </tbody>
            </table>
          </div>

        </div>}

        {view==="nuevo"&&isAdmin&&<NuevoCreditoForm lineas={lineas} onCreate={createCredito}/>}
        {view==="lineas"&&isAdmin&&<LineasManager lineas={lineas} onSave={saveLineas}/>}
        {view==="usuarios"&&isAdmin&&<UsuariosManager usuarios={usuarios} onSave={saveUsuarios}/>}
        {view==="apariencia"&&isAdmin&&<AparienciaManager tema={tema} onSave={saveTema}/>}
        {view==="encabezado"&&isAdmin&&<ConfigHeader config={config} onSave={saveCfg}/>}
        {view==="perfil"&&<PerfilForm user={user} onSave={actualizarPerfil}/>}
      </div>
    </div>

    {selected&&<CreditoDetalle
      credito={selected}
      linea={lineas.find(l=>l.id===selected.lineaId)}
      rol={user.rol}
      config={config}
      onClose={()=>setSelected(null)}
      onUpdate={updateCredito}
      onDelete={deleteCredito}
      onGoHome={()=>{setSelected(null);setView("inicio");}}
    />}

    {/* Simulador de cuotas modal */}
    {showSimulador&&<SimuladorCuotas lineas={lineas} onClose={()=>setShowSimulador(false)} onPrint={imprimirHTML}/>}
    {showEstadoCuenta&&<EstadoCuentaListado creditos={creditosVisibles} lineas={lineas} onClose={()=>setShowEstadoCuenta(false)} onPrint={imprimirHTML} onSelectCredito={c=>{setShowEstadoCuenta(false);setSelected(c);}}/>}

    {/* Chat DM flotante — siempre visible */}
    <ChatDM user={user} usuarios={usuarios}/>

    {/* Área global de impresión */}
    <div id="print-area" dangerouslySetInnerHTML={{__html:printHTML||""}}/>
  </div>;
}

export default function App(){
  return <ErrorBoundary><CrecerApp/></ErrorBoundary>;
}
